    # The underlying pattern is constant down each column; use its most
    # frequent visible value to recover each column's value.
    base = []
    for c in range(w):
        counts = {}
        for r in range(h):
            v = grid[r][c]
            if v != 0:
                counts[v] = counts.get(v, 0) + 1
        base.append(max(counts, key=counts.get) if counts else 0)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                if r == c and r > 0:
                    out[r][c] = base[c - 1]
                else:
                    out[r][c] = base[c]
    return out
