def transform(grid):
    h, w = len(grid), len(grid[0])
    votes = [{} for _ in range(w)]

    # Recover the first-row sequence b. Above/on the diagonal a cell
    # represents b[c]; below the diagonal it represents b[c+1].
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                j = c if c >= r else c + 1
                if j < w:
                    votes[j][v] = votes[j].get(v, 0) + 1

    b = [None] * w
    for j in range(w):
        if votes[j]:
            b[j] = max(votes[j], key=votes[j].get)

    # Fill any unobserved sequence positions by continuing the visible
    # cyclic sequence.
    for j in range(w):
        if b[j] is None:
            for d in range(1, w + 1):
                if j - d >= 0 and b[j - d] is not None:
                    b[j] = b[j - d]
                    break
                if j + d < w and b[j + d] is not None:
                    b[j] = b[j + d]
                    break

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] == 0:
                j = c if c >= r else c + 1
                out[r][c] = b[j] if j < w else b[-1]
    return out
